def partition(weight):
    if weight <= 0:
        return 'invalid-low'
    if weight <= 2:
        return 'standard'
    if weight <= 20:
        return 'heavy'
    return 'rejected'

def representatives(weights):
    reps = {}
    for w in weights:
        reps.setdefault(partition(w), w)
    return reps

