def ep_tests(fields):
    base = {name: spec['valid'] for name, spec in fields.items()}
    tests = [dict(base)]
    for name, spec in fields.items():
        for bad in spec['invalid']:
            case = dict(base)
            case[name] = bad
            tests.append(case)
    return tests
